import{_ as n,C as i,c as d,o as h,j as e,G as o,a3 as a,a as r}from"./chunks/framework.Dokpd4od.js";const m=JSON.parse('{"title":"Inventory overview","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/inventories/get-started/inventory-overview.md","filePath":"master/supply-chain/inventories/get-started/inventory-overview.md","lastUpdated":1791902625000}'),l={name:"master/supply-chain/inventories/get-started/inventory-overview.md"};function g(u,t,c,p,v,b){const s=i("ImagePopup");return h(),d("div",null,[t[0]||(t[0]=e("h1",{id:"inventory-overview",tabindex:"-1"},[r("Inventory overview "),e("a",{class:"header-anchor",href:"#inventory-overview","aria-label":'Permalink to "Inventory overview"'},"​")],-1)),t[1]||(t[1]=e("p",null,"The Overview is the first screen of Inventory. It shows one card for each type of operation, such as Receipts or Delivery Orders. Each card tells you how much work is waiting and lets you jump straight to it.",-1)),t[2]||(t[2]=e("blockquote",null,[e("p",null,[e("strong",null,"In simple words:"),r(" The Overview is your daily to-do board for the warehouse.")])],-1)),t[3]||(t[3]=e("p",null,[r("Open it with "),e("code",null,"Inventory → Overview"),r(".")],-1)),o(s,{src:"/images1/inventory/ov_dashboard_all.png",alt:"Inventory Overview dashboard with the All tab and operation cards"}),t[4]||(t[4]=a('<h2 id="tabs" tabindex="-1">Tabs <a class="header-anchor" href="#tabs" aria-label="Permalink to &quot;Tabs&quot;">​</a></h2><p>The tabs at the top filter the cards by kind of operation.</p><ul><li><strong>All:</strong> Every card.</li><li><strong>Receipts:</strong> Cards that bring goods in, such as Receipts and PoS Returns.</li><li><strong>Delivery Orders:</strong> Cards that send goods out, such as Delivery Orders and PoS Orders.</li><li><strong>Internal Transfers:</strong> Cards that move goods inside the warehouse, such as Pick, Pack, Quality Control and Storage.</li></ul><h2 id="read-a-card" tabindex="-1">Read a card <a class="header-anchor" href="#read-a-card" aria-label="Permalink to &quot;Read a card&quot;">​</a></h2><p>Each card is one operation type. The heading is a link to the list of that operation. The small grey text under it is the warehouse.</p>',5)),o(s,{src:"/images1/inventory/ov_card_closeup.png",alt:"Close-up of the Receipts card showing 1 To Receive, 1 Late and 1 Operations links"}),t[5]||(t[5]=a('<table tabindex="0"><thead><tr><th>Item</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Open</strong></td><td>Nothing is ready. Click to open the list anyway.</td></tr><tr><td><strong>N To Receive</strong></td><td>N receipts are Ready. Click to see them.</td></tr><tr><td><strong>N To Deliver</strong></td><td>N deliveries are Ready.</td></tr><tr><td><strong>N To Process</strong></td><td>N internal transfers are Ready.</td></tr><tr><td><strong>N Waiting</strong></td><td>N operations wait for stock or for another step.</td></tr><tr><td><strong>N Late</strong></td><td>N operations are past their scheduled date.</td></tr><tr><td><strong>N Back Orders</strong></td><td>N operations have a backorder behind them.</td></tr><tr><td><strong>N Operations</strong></td><td>All open operations of this type.</td></tr></tbody></table><p>A link only shows when its number is above zero. Every link opens the matching list, already filtered.</p><h3 id="the-bar-chart" tabindex="-1">The bar chart <a class="header-anchor" href="#the-bar-chart" aria-label="Permalink to &quot;The bar chart&quot;">​</a></h3><p>Under each card, a small chart counts open operations by scheduled day. The bars are <strong>Before</strong>, <strong>Yesterday</strong>, <strong>Today</strong>, <strong>Tomorrow</strong>, <strong>The day after tomorrow</strong> and <strong>After</strong>. Red bars are late, blue is today and green is in the future. Grey bars mean there is no data yet.</p><h2 id="menu-tour" tabindex="-1">Menu tour <a class="header-anchor" href="#menu-tour" aria-label="Permalink to &quot;Menu tour&quot;">​</a></h2><p>The top bar holds six menus.</p><table tabindex="0"><thead><tr><th>Menu</th><th>What it holds</th></tr></thead><tbody><tr><td><strong>Overview</strong></td><td>This dashboard</td></tr><tr><td><strong>Operations</strong></td><td>Receipts, Deliveries, Internal Transfers, Dropships, Quantities and Scraps</td></tr><tr><td><strong>Products</strong></td><td>Products, Packages, Lots / Serial Numbers</td></tr><tr><td><strong>Reporting</strong></td><td>Moves History and Locations (stock report)</td></tr><tr><td><strong>Configurations</strong></td><td>Warehouse Management, Products, Delivery, Units of Measure</td></tr><tr><td><strong>Settings</strong></td><td>Five settings pages</td></tr></tbody></table><h3 id="which-setting-reveals-which-menu" tabindex="-1">Which setting reveals which menu <a class="header-anchor" href="#which-setting-reveals-which-menu" aria-label="Permalink to &quot;Which setting reveals which menu&quot;">​</a></h3><table tabindex="0"><thead><tr><th>You see this menu</th><th>When this setting is on</th></tr></thead><tbody><tr><td>Operations → <strong>Dropships</strong></td><td><strong>Dropshipping</strong></td></tr><tr><td>Products → <strong>Packages</strong></td><td><strong>Packages</strong></td></tr><tr><td>Products → <strong>Lots / Serial Numbers</strong></td><td><strong>Lots &amp; Serial Numbers</strong></td></tr><tr><td>Configurations → <strong>Locations</strong></td><td><strong>Locations</strong></td></tr><tr><td>Configurations → <strong>Routes</strong> and <strong>Rules</strong></td><td><strong>Multi Steps Routes</strong></td></tr><tr><td>Configurations → <strong>Attributes</strong></td><td><strong>Variants</strong></td></tr><tr><td>Configurations → <strong>Packagings</strong></td><td><strong>Packagings</strong></td></tr><tr><td>Configurations → <strong>Package Types</strong></td><td><strong>Packages</strong></td></tr><tr><td>Configurations → <strong>UOM Categories</strong></td><td><strong>Unit of Measure</strong></td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The Configurations menu has four groups: <strong>Warehouse Management</strong> (Warehouses, Locations, Operation Types, Routes, Rules, Storage Categories, Putaway Rules), <strong>Products</strong> (Categories, Attributes, Packagings), <strong>Delivery</strong> (Package Types) and <strong>Units of Measure</strong> (UOM Categories).</p></div><h2 id="behind-the-scenes" tabindex="-1">Behind the scenes <a class="header-anchor" href="#behind-the-scenes" aria-label="Permalink to &quot;Behind the scenes&quot;">​</a></h2><p>The cards are built from your operation types. When you add a warehouse with more steps, new cards such as Pick, Pack or Storage appear. They live under the <strong>Internal Transfers</strong> tab.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./inventory-settings.html">Inventory settings</a></li><li><a href="./first-steps.html">First steps</a></li><li><a href="./../warehouses/operation-types.html">Operation types</a></li><li><a href="./../operations/receipts.html">Receipts</a></li></ul>',14))])}const f=n(l,[["render",g]]);export{m as __pageData,f as default};
